/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import crypto from 'node:crypto';
const paths = ['yss-project.yaml','AGENTS.md','CONTEXT.md','plan.md','state.json','review.json','reconciliation.json','entry-result.json','approval/decision.json','approval/requester.json','approval/reply-0.json','approval/presentation.json','docs/.scratch/demo/spec.md','docs/.scratch/demo/parent-ticket.md','docs/.scratch/demo/entry-work-record.md','.template-spec/process/lifecycle-registry.yaml','.template-spec/agents/issue-tracker.md'];
const digest = p => 'sha256:' + crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const snapshot = Object.fromEntries(paths.map(p => [p, digest(p)]));
const review = JSON.parse(fs.readFileSync('review.json','utf8'));
const basis = review.basis.map(b=>({ref:b.ref,expected:b.digest,actual:digest(b.ref),current:b.digest===digest(b.ref)}));
console.log(JSON.stringify({snapshot,basis,result_exists:fs.existsSync('resume-result.json')},null,2));
NODE"

